<template>
    <div class="playlist-preview" :class="{
        row: props.row,
        invert: props.invert,
        disabled: props.disabled
    }">
        <div>
            <div class="cover" :class="{ disabled: false }">
                <Img v-if="cover?.resized || defaultCover?.resized"
                    :preview="cover?.resized || defaultCover?.resized"
                    :original="cover?.original || defaultCover?.original"
                    :skeleton="true"
                    :wathermark="props.item.type === 'EDITORIAL' ? 'playlists' : null"
                />

                <div class="buttons">
                    <IconButton
                        @click.stop="open"
                        class="open size-s tertiary invert"
                        icon="preview-list"
                    />

                    <AudioToggle
                        :state="state"
                        @play="play"
                        @pause="pause"
                    />
                </div>

                <div v-if="props.item.type === 'EDITORIAL'" class="logo">
                    <Icon icon="editorial" />
                    <Icon icon="editorial" />
                </div>
            </div>
            <State v-if="!props.row && props.showState && props.item?.state" 
                :state="props.item?.state"
                class="solid" />
        </div>
        <div>
            <div>
                <span class="title">
                    {{ (props.item?.title ? props.item?.title['en-US'] : props.item?.title) || t('playlists.empty-name') }}
                </span>
               
                <State v-if="props.row && props.showState && props.item?.state" 
                    :state="props.item?.state"
                />
            </div>
        </div>
    </div>
</template>

<script setup>
    import { onMounted, reactive, computed } from 'vue';
    import { useI18n } from 'vue-i18n';
    import moment from 'moment';
    import Button from '🔗/components/ui/Button.vue';
    import IconButton from '🔗/components/ui/IconButton.vue';
    import Img from '🔗/components/ui/Img.vue';
    import AudioToggle from '🔗/components/ui/AudioToggle.vue';

    import api from '🔗/api';
    import stores from '@/stores';
    import State from '🔗/components/ui/State.vue';

    const player = stores.player();
    const modals = stores.modals();


    const emit = defineEmits(['change']);

    const { t } = useI18n();

    const props = defineProps({
        item: { type: Object, default: () => ({}) },
        showState: { type: Boolean, default: false },
        row: { type: Boolean, default: false },
        invert: { type: Boolean, default: false },
        disabled: { type: Boolean, default: false }
    });

    const cover = computed(() => {
        let url;
        if (props.item?.cover instanceof File) {
            url = URL.createObjectURL(props.item.cover);
        }

        return url ? {
            resized: url,
            cover: url,
            original: url
        } : props.item?.cover;
    });

    const data = reactive({
    });


    const defaultCover = computed(() => {
        return api.playlists().defaultCover;
    });

    const open = () => {
        if (!props.item?.id) {
            return;
        }

        modals.reopen('playlist', {
            data: props.item?.id,
            popover: true
        })
    }

    const state = computed(() => {
        if (!player.panes.default || player.panes.default._queue?.playlist?.id !== props.item?.id) {
            return;
        }

        return player.panes.default._state;
    });

    const getTracks = async () => {
        const payload = await api.playlists().tracks.list(props.item.id) || [];
        return payload?.items || [];
    }

    const pause = async () => {
        // Если не наш плейлист играет, ничего не делаем
        if (player.panes.default?._queue?.playlist?.id !== props.item?.id) {
            return;
        }

        // Если идет воспроизведение
        if (state.value === 'playing') {
            player.panes.default.pause();
            return;
        }
    }

    const play = async () => {
        // Если там не этот плейлист включен
        if (player.panes.default?._queue?.playlist?.id !== props.item?.id) {
            const tracks = await getTracks();

            if (!tracks?.length) {
                return;
            }

            const queue = await player.trackQueue(tracks, { type: 'playlist', playlist: props.item });

            if (!queue?.items?.length) {
                return;
            }

            const track = await player.track(queue.items[0]);
            track.play();
            return;
        }

        const queue = player.panes.default.queue();

        // Если стоит на паузе
        if (player.panes.default._state === 'paused') {
            player.panes.default.resume();
            return;
        }
    }
</script>

<style lang="scss" scoped>
    .playlist-preview {
        display: flex;
        flex-direction: column;
        align-items: stretch;
        gap: 8px;
        width: 100%;
        overflow: hidden;
        & > div {
            &:first-child {
                display: flex;
                flex-direction: column;
                gap: 8px;
                position: relative;

                .cover {
                    width: 136px;
                    height: 136px;
                    position: relative;

                    .wathermark,
                    .skeleton-wrapper,
                    img {
                        width: 100%;
                        height: 100%;
                        border-radius: 10px;
                        object-fit: cover;
                        overflow: hidden;
                    }

                    .buttons {
                        position: absolute;
                        // top: 0;
                        left: 0;
                        right: 0;
                        bottom: 0;
                        display: flex;
                        flex-direction: row;
                        gap: 4px;
                        padding: 8px;
                        height: auto;
                        justify-content: end;
                        align-items: center;
                        .open {
                            opacity: 0;
                            transition: opacity .2s;
                        }
                        .audio-toggle {
                            width: 34px;
                            height: 34px;
                            background: transparent;
                        }
                    }


                    &:hover {
                        .buttons {
                            .open {
                                opacity: 1;
                            }
                            .audio-toggle {
                                opacity: 1;
                            }
                        }

                    }

                    .logo {
                        position: absolute;
                        left: 8px;
                        bottom: 8px;
                        width: 36px;
                        height: 36px;
                        opacity: .6;
                        svg {
                            display: block;
                            fill: var(--light-80);
                        }
                        @include svg-skeleton(3s, 25deg, 0);
                    }

                    &.disabled {
                        filter: grayscale(1);
                        .skeleton-wrapper,
                        img {
                            cursor: default;
                        }
                    }
                }

                .state {
                    position: absolute;
                    right: 8px;
                    top: 8px;
                }
            }
            &:last-child {
                display: flex;
                flex-direction: column;
                gap: 4px;
                flex: 1;
                min-width: 0;

                & > div {
                    display: flex;
                    flex-direction: row;
                    align-items: baseline;
                    gap: 4px;
                    min-width: 0;

                    &:first-child {
                        flex-wrap: nowrap;
                    }
                    &:last-child {
                        flex-direction: column;
                        width: 100%;
                    }

                    .title {
                        font: var(--font-body-1);
                        color: var(--dark-500);
                        // white-space: nowrap;
                        // text-overflow: ellipsis;
                        // overflow: hidden;
                    }

                    .tag {
                        white-space: nowrap;
                        font: var(--font-label);
                        background: var(--gray-90);
                        padding: 4px 8px;
                        border-radius: 10px;
                        color: var(--white-500);
                        flex-shrink: 0;
                    }

                    .state {
                    }
                }
            }
        }

        &.disabled {
            opacity: .4;
            filter: grayscale(1);
            cursor: default;
        }

        &.row {
            flex-direction: row;
            & > div {
                &:first-child {
                    .cover {
                       width: 70px;
                       height: 70px;

                        .logo {
                            left: 6px;
                            bottom: 4px;
                            width: 16px;
                            height: 16px;
                            opacity: 1;
                        }

                        .buttons {
                            top: 0;
                            height: auto;
                            padding: 0;

                            .open {
                                display: none;
                            }

                            .audio-toggle {
                                position: absolute;
                                top: 0;
                                left: 0;
                                right: 0;
                                bottom: 0;
                                width: 100%;
                                height: 100%;
                            }
                       }
                    }

                    .state {
                    }
                }
                &:last-child {

                    & > div {
                        &:first-child {
                        }
                        &:last-child {
                            align-items: start;
                        }

                        
                    }
                }
            }
        }


        &.invert {
            & > div:last-child {
                & > div {
                    .title {
                        color: var(--white-500);           
                    }
                }
            }
        }
    }
</style>